"""Deterministic structural control-flow diagrams, never generated by AI."""
import ast
import html
from fastapi import HTTPException


class Diagram:
    def __init__(self, source):
        self.source = source
        self.lines = ['flowchart TD']
        self.count = 0
        self.functions = []
        self.notes = set()

    def node(self, text, decision=False):
        self.count += 1
        if self.count > 240:
            raise HTTPException(422, 'This diagram is too large. Try a smaller function (up to 240 diagram nodes).')
        key = f'N{self.count}'
        # Entity encoding prevents source strings from injecting Mermaid syntax/HTML.
        text = html.escape(text[:140], quote=True).replace('\n', ' ')
        text = text.replace('`', '&#96;').replace('\\', '&#92;')
        for character in '%{}[]':
            text = text.replace(character, f'&#{ord(character)};')
        shape = '{"' + text + '"}' if decision else '["' + text + '"]'
        self.lines.append(key + shape)
        return key

    def edge(self, source, target, label=''):
        self.lines.append(f'{source} -->' + (f'|{label}|' if label else '') + f' {target}')

    def title(self, node):
        segment = ast.get_source_segment(self.source, node) or type(node).__name__
        return f'L{node.lineno}: ' + segment.splitlines()[0].strip()

    def block(self, statements, destination, loop=None):
        next_node = destination
        for node in reversed(statements):
            label = self.title(node)
            if isinstance(node, ast.If):
                current = self.node(label, True)
                self.edge(current, self.block(node.body, next_node, loop), 'Yes')
                self.edge(current, self.block(node.orelse, next_node, loop), 'No')
            elif isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
                current = self.node(label, True)
                # break bypasses loop-else; exhaustion goes through it.
                exhausted = self.block(node.orelse, next_node, loop)
                body = self.block(node.body, current, (next_node, current))
                self.edge(current, body, 'Iterate')
                self.edge(current, exhausted, 'Finished')
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                current = self.node(f'L{node.lineno}: define {node.name} (body shown separately)')
                self.functions.append(node)
                self.edge(current, next_node)
            elif isinstance(node, (ast.Return, ast.Raise)):
                current = self.node(label)
                self.edge(current, self.node('Return to caller' if isinstance(node, ast.Return) else 'Raise exception'))
                if isinstance(node, ast.Raise):
                    self.notes.add('Exception handlers and finally paths are not expanded.')
            elif isinstance(node, (ast.Break, ast.Continue)):
                current = self.node(label)
                if loop:
                    self.edge(current, loop[0 if isinstance(node, ast.Break) else 1])
                else:
                    self.edge(current, next_node)
            else:
                current = self.node(label)
                self.edge(current, next_node)
                if isinstance(node, (ast.Try, ast.TryStar, ast.With, ast.AsyncWith, ast.Match, ast.ClassDef)):
                    self.notes.add('try/with/match/class bodies are collapsed; this is a structural overview, not a full control-flow graph.')
            next_node = current
        return next_node


def create_flowchart(source):
    tree = ast.parse(source)
    diagram = Diagram(source)
    end = diagram.node('End module')
    start = diagram.node('Start module')
    diagram.edge(start, diagram.block(tree.body, end))
    position = 0
    while position < len(diagram.functions):
        function = diagram.functions[position]
        position += 1
        entry = diagram.node(f'Function {function.name} (L{function.lineno})')
        exit_node = diagram.node(f'End {function.name} / return')
        diagram.edge(entry, diagram.block(function.body, exit_node))
    return {'mermaid':'\n'.join(diagram.lines), 'label':'Generated from Python AST',
        'notes':sorted(diagram.notes) + ['Function bodies are separate diagrams; calls are shown as source statements. Expression internals and implicit exception paths are not expanded.'],
        'node_count':diagram.count}
